def count_pairs(n, a):
    counter = Counter()
    result = 0

    for num in a:
        value = 0
        while num > 0:
            if num % 2 == 1:
                value += 1
            num //= 2
        counter[value] += 1

    for count in counter.values():
        if count > 1:
            result += count * (count - 1) // 2

    return result

